#pragma once

#include <cstddef>
#include <cstdint>
#include <memory>

#include "FrameFormat.h"

namespace camera {

// ============================================================================
// IFrameDecoder -- abstraction over a compressed-frame decoder.
//
// Decouples the HAL session from any specific codec: the session asks for
// "decode source format X into destination format Y" and gets back a decoder
// that reports its *actual* output geometry (via outputFormat()), instead of
// hardcoding a specific decoder + assuming NV12 4:2:0. A new compressed source
// (e.g. H.264 frames) only needs a factory entry (MediaCodecDecoder already
// generalizes over MediaCodec MIME types).
//
// Thread safety: implementations are NOT internally synchronized; the caller
// must serialize configure()/decode()/reset() (session holds decoderMutex_).
// ============================================================================
class IFrameDecoder {
public:
    virtual ~IFrameDecoder() = default;

    /**
     * Configure the decoder for a given source geometry.
     * @param in  Source format (fourcc + width + height). Compressed input.
     * @param out [out] Filled with the decoder's ACTUAL output format
     *            (fourcc + plane layout). Used by the caller to size buffers.
     * @return true if the decoder is ready.
     */
    virtual bool configure(const FrameFormat& in, FrameFormat* out) = 0;

    /**
     * Decode one compressed frame into the caller's output buffer.
     * The output layout matches outputFormat().
     * @return true on success; false leaves the output buffer undefined.
     */
    virtual bool decode(const uint8_t* in, size_t inSize, uint8_t* out, size_t outSize,
                        size_t* actualOutputSize) = 0;

    virtual bool isReady() const = 0;

    /** Actual output format reported after a successful configure(). */
    virtual const FrameFormat& outputFormat() const = 0;

    /** Human-readable backend name for logging. */
    virtual const char* backendName() const = 0;
};

/**
 * Create a decoder that converts srcFourcc -> dstFourcc.
 * @return nullptr if no decoder can satisfy the pair (caller must handle).
 *
 * Currently supported: MJPG -> NV12. Add cases here as new codecs land.
 */
std::unique_ptr<IFrameDecoder> createFrameDecoder(uint32_t srcFourcc, uint32_t dstFourcc);

} // namespace camera
