#pragma once

#include <cstddef>
#include <cstdint>
#include <memory>

#include "FrameFormat.h"

namespace camera {

// ============================================================================
// IFrameEncoder -- abstraction over a raw-frame encoder (symmetric to
// IFrameDecoder). Where the decoder does "compressed source -> canonical
// NV12", the encoder does "canonical NV12 -> compressed target". Together they
// let the data plane act as a transcode hub: any source decodes to NV12, any
// output re-encodes from NV12.
//
// The concrete codec is chosen by the target fourcc (JPEG / H.264) at factory
// time; whether a backend actually exists is decided by media_codec, so the
// control plane can reject an output up front instead of failing at runtime.
//
// Thread safety: implementations are NOT internally synchronized; the caller
// must serialize configure()/encode() (session holds decoderMutex_).
// ============================================================================
class IFrameEncoder {
public:
    virtual ~IFrameEncoder() = default;

    struct Params {
        uint32_t bitrate = 0;   /* video: target bitrate (bps); JPEG ignores */
        uint32_t framerate = 0; /* video: target framerate (fps); JPEG ignores */
        uint32_t quality = 0;   /* JPEG: quality 1..100 (0 => default); video ignores */
    };

    /**
     * Configure the encoder for a given NV12 input geometry.
     * @param in      Source format; must be NV12 (the canonical intermediate).
     * @param params  Codec parameters (bitrate/framerate for video, quality
     *                for JPEG); zero fields fall back to defaults.
     * @return true if the encoder is ready.
     */
    virtual bool configure(const FrameFormat& in, const Params& params) = 0;

    /**
     * Encode one NV12 frame into the caller's output buffer.
     * @param nv12        Packed NV12 input (layout matches configure()'s in).
     * @param out         Destination buffer for the compressed unit.
     * @param outCap      Capacity of out in bytes.
     * @param actualSize  [out] Compressed byte count written.
     * @param isKeyFrame  [out] Optional; true if the unit is a key frame
     *                    (video). May be nullptr. For JPEG always true.
     * @return true on success; false leaves the output buffer undefined.
     */
    virtual bool encode(const uint8_t* nv12, size_t nv12Size, uint8_t* out, size_t outCap,
                        size_t* actualSize, bool* isKeyFrame) = 0;

    virtual bool isReady() const = 0;

    /** Compressed target fourcc this encoder produces (e.g. H264, MJPG). */
    virtual uint32_t outputFourcc() const = 0;

    /** Human-readable backend name for logging. */
    virtual const char* backendName() const = 0;
};

/**
 * Create an encoder that produces the given compressed target fourcc from NV12.
 * @param dstFourcc  Target compressed format (MJPG/JPEG or H264).
 * @return nullptr if no encoder backend exists for it (caller must handle).
 *
 * Backend availability is platform-dependent: sim has an H.264 encoder but no
 * M2M JPEG encoder, so createFrameEncoder(H264) is non-null while
 * createFrameEncoder(MJPG) is null on sim.
 */
std::unique_ptr<IFrameEncoder> createFrameEncoder(uint32_t dstFourcc);

} // namespace camera
