#pragma once

#include <cstddef>
#include <cstdint>
#include <vector>

namespace camera {

// ============================================================================
// FrameFormat -- a self-describing pixel format + geometry descriptor.
//
// Purpose: carry format/geometry as *data* through the multi-stream pipeline
// (negotiation -> decode -> dispatch) instead of having each stage re-derive
// it from the hardcoded "source=MJPEG, output=NV12 4:2:0, stride==width"
// assumption. Buffer sizes are computed from the actual plane layout via
// totalSize() rather than a scattered `w*h*3/2`.
// ============================================================================

/** Build a V4L2-style fourcc from 4 chars (matches V4L2_PIX_FMT_* values). */
constexpr uint32_t makeFourcc(char a, char b, char c, char d) {
    return static_cast<uint32_t>(a) | (static_cast<uint32_t>(b) << 8) |
            (static_cast<uint32_t>(c) << 16) | (static_cast<uint32_t>(d) << 24);
}

namespace pixfmt {
// Values intentionally match the V4L2 fourcc constants (V4L2_PIX_FMT_*),
// declared here to avoid a hard dependency on <sys/videoio.h>.
constexpr uint32_t UNKNOWN = 0;
constexpr uint32_t NV12 = makeFourcc('N', 'V', '1', '2'); /* Y + interleaved UV, 4:2:0 */
constexpr uint32_t MJPG = makeFourcc('M', 'J', 'P', 'G'); /* Motion-JPEG / JPEG */
constexpr uint32_t H264 = makeFourcc('H', '2', '6', '4'); /* H.264 / AVC */
constexpr uint32_t HEVC = makeFourcc('H', 'E', 'V', 'C'); /* H.265 / HEVC */
} // namespace pixfmt

/** One plane's byte layout. rows*stride bytes starting at offset. */
struct PlaneLayout {
    uint32_t stride = 0; /* row length in bytes, incl. padding (V4L2 bytesperline) */
    uint32_t offset = 0; /* byte offset from buffer start */
    uint32_t rows = 0;   /* number of rows in this plane */
};

struct FrameFormat {
    uint32_t fourcc = pixfmt::UNKNOWN;
    uint32_t width = 0;
    uint32_t height = 0;
    std::vector<PlaneLayout> planes;

    bool valid() const {
        return fourcc != pixfmt::UNKNOWN && width > 0 && height > 0;
    }

    /** Total buffer bytes implied by the plane layout. 0 for compressed
     * formats with no planes (their size is variable / runtime-known). */
    size_t totalSize() const {
        size_t s = 0;
        for (const auto& p : planes) {
            const size_t end =
                    static_cast<size_t>(p.offset) + static_cast<size_t>(p.stride) * p.rows;
            if (end > s) s = end;
        }
        return s;
    }

    // ---- Factory helpers for the common formats ----

    /** Packed NV12 (stride==width, no padding): Y plane then interleaved UV. */
    static FrameFormat nv12(uint32_t w, uint32_t h) {
        FrameFormat f;
        f.fourcc = pixfmt::NV12;
        f.width = w;
        f.height = h;
        f.planes.push_back({/*stride*/ w, /*offset*/ 0, /*rows*/ h});         /* Y  */
        f.planes.push_back({/*stride*/ w, /*offset*/ w * h, /*rows*/ h / 2}); /* UV */
        return f;
    }

    /** Compressed source format (no fixed plane layout). */
    static FrameFormat compressed(uint32_t fourcc, uint32_t w, uint32_t h) {
        FrameFormat f;
        f.fourcc = fourcc;
        f.width = w;
        f.height = h;
        return f;
    }
};

} // namespace camera
