// ============================================================================
// Codec pipeline capability gate.
//
// The service codec pipeline provides source fan-out plus an on-the-fly format
// transform. Its two capabilities have independent dependencies:
//   - pixel conversion / scaling (RAW<->RAW, e.g. YUV->RGB) needs only libyuv;
//   - compressed decode/encode (MJPEG->NV12 / NV12->JPEG) additionally needs
//     the MediaCodec backend (CONFIG_MEDIA_CODEC, which pulls in libmedia).
//
// The pipeline is therefore available whenever EITHER capability is present:
// with libyuv alone it serves RAW sources (format-conversion path), and with
// media codec it additionally serves compressed sources/sinks. Only the
// compressed decode/encode + JPEG BLOB assembly stays behind CONFIG_MEDIA_CODEC.
// ============================================================================
#if defined(CONFIG_LIBYUV) || defined(CONFIG_MEDIA_CODEC)
#  define CAMERA_CODEC_PIPELINE_AVAILABLE 1
#endif

