#include "IFrameDecoder.h"
#include "MediaCodecDecoder.h"

namespace camera {

// ============================================================================
// Decoder factory -- maps a (srcFourcc -> dstFourcc) pair to an implementation.
//
// Policy: use the generic MediaCodec (V4L2 M2M hardware) adapter for any codec
// it supports. Adding a new compressed source (e.g. H.264) usually only needs a
// fourcc->MIME entry in MediaCodecDecoder -- no change here.
// ============================================================================
std::unique_ptr<IFrameDecoder> createFrameDecoder(uint32_t srcFourcc, uint32_t dstFourcc) {
    if (dstFourcc != pixfmt::NV12) {
        return nullptr; /* only NV12 output is supported today */
    }

    /* Hardware MediaCodec if available for this source format. */
    if (MediaCodecDecoder::available(srcFourcc)) {
        return std::unique_ptr<IFrameDecoder>(new MediaCodecDecoder());
    }

    return nullptr;
}

} // namespace camera
