#include "IFrameEncoder.h"
#include "MediaCodecEncoder.h"

namespace camera {

// ============================================================================
// Encoder factory -- maps a target compressed fourcc to an implementation.
//
// Symmetric to createFrameDecoder: use the generic MediaCodec (V4L2 M2M
// hardware) adapter for any codec it supports. Returns nullptr when no backend
// exists, so the control plane can reject that output up front. The input is
// always canonical NV12 (the data plane's intermediate format).
// ============================================================================
std::unique_ptr<IFrameEncoder> createFrameEncoder(uint32_t dstFourcc) {
    if (MediaCodecEncoder::available(dstFourcc)) {
        return std::unique_ptr<IFrameEncoder>(new MediaCodecEncoder(dstFourcc));
    }
    return nullptr;
}

} // namespace camera
