/****************************************************************************
 * frameworks/multimedia/camera/common/MediaCodecBase.h
 *
 * SPDX-License-Identifier: Apache-2.0
 *
 * Shared V4L2 M2M (media_codec) plumbing for the MediaCodec-backed IFrame*
 * implementations. Not an IFrame* itself: it owns the codec lifecycle
 * (create/stop/release), the fourcc->MIME map, backend availability probing,
 * and the "dequeue input -> fill -> queue input" submit dance that the
 * decoder and encoder share. MediaCodecDecoder / MediaCodecEncoder mix this in
 * (alongside their IFrame* interface) and add the direction-specific
 * configure() + decode()/encode() and the NV12<->I420 fixups.
 *
 * Thread safety: not internally synchronized; the caller serializes access
 * (session holds decoderMutex_), same contract as the IFrame* interfaces.
 ****************************************************************************/

#pragma once

#include <cstddef>
#include <cstdint>
#include <vector>

namespace camera {

class MediaCodecBase {
public:
    MediaCodecBase() = default;
    ~MediaCodecBase();

    MediaCodecBase(const MediaCodecBase&) = delete;
    MediaCodecBase& operator=(const MediaCodecBase&) = delete;

protected:
    /** Map an MJPG/H264/HEVC fourcc to a MediaCodec MIME string; nullptr if none. */
    static const char* fourccToMime(uint32_t fourcc);

    /** Probe whether a MediaCodec exists for fourcc (isEncoder: false=decode). */
    static bool availableFor(uint32_t fourcc, bool isEncoder);

    /** dequeue_input -> fill (or USERPTR pass-through) -> queue_input. */
    bool submitInput(const uint8_t* in, size_t inSize);

    /** Stop + release the codec and reset state. Idempotent. */
    void destroyCodec();

    void* codec_ = nullptr; /* media_codec_t */
    uint32_t width_ = 0;
    uint32_t height_ = 0;
    bool configured_ = false;
    std::vector<uint8_t> i420Buf_; /* scratch for NV12<->I420 conversion */
};

} /* namespace camera */
