/****************************************************************************
 * frameworks/multimedia/camera/common/MediaCodecBase.cpp
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#define LOG_TAG "MediaCodecBase"
#include "MediaCodecBase.h"

#include <algorithm>
#include <cstring>

#include "CameraUtils.h"
#include "FrameFormat.h"

#ifdef CONFIG_MEDIA_CODEC
#include <media_codec.h>
#include <sys/videoio.h>
#endif

namespace camera {

const char* MediaCodecBase::fourccToMime(uint32_t fourcc) {
#ifdef CONFIG_MEDIA_CODEC
    switch (fourcc) {
        case pixfmt::MJPG:
            return MEDIA_MIMETYPE_IMAGE_JPEG;
        case pixfmt::H264:
            return MEDIA_MIMETYPE_VIDEO_AVC;
        case pixfmt::HEVC:
            return MEDIA_MIMETYPE_VIDEO_HEVC;
        default:
            return nullptr;
    }
#else
    (void)fourcc;
    return nullptr;
#endif
}

bool MediaCodecBase::availableFor(uint32_t fourcc, bool isEncoder) {
#ifdef CONFIG_MEDIA_CODEC
    const char* mime = fourccToMime(fourcc);
    if (!mime) {
        return false;
    }
    media_codec_t test = media_codec_create_by_type(
            mime, isEncoder ? MEDIA_CODEC_ENCODER : MEDIA_CODEC_DECODER);
    if (test) {
        media_codec_release(test);
        return true;
    }
#else
    (void)fourcc;
    (void)isEncoder;
#endif
    return false;
}

MediaCodecBase::~MediaCodecBase() {
    destroyCodec();
}

void MediaCodecBase::destroyCodec() {
#ifdef CONFIG_MEDIA_CODEC
    if (codec_) {
        media_codec_stop(static_cast<media_codec_t>(codec_));
        media_codec_release(static_cast<media_codec_t>(codec_));
        codec_ = nullptr;
    }
#endif
    configured_ = false;
    i420Buf_.clear();
    i420Buf_.shrink_to_fit();
}

bool MediaCodecBase::submitInput(const uint8_t* in, size_t inSize) {
#ifdef CONFIG_MEDIA_CODEC
    auto* codec = static_cast<media_codec_t>(codec_);

    media_codec_buffer_t inBuf = {};
    int ret = media_codec_dequeue_input(codec, &inBuf, 1000);
    if (ret != 0) {
        CLOGW("dequeue_input failed: %d", ret);
        return false;
    }

    /* data may be NULL in USERPTR/DMABUF mode -- pass our own buffer then. */
    size_t copyIn = std::min(inSize, inBuf.capacity > 0 ? inBuf.capacity : inSize);
    if (inBuf.data != nullptr) {
        memcpy(inBuf.data, in, copyIn);
    } else {
        inBuf.data = const_cast<uint8_t*>(in);
    }
    inBuf.size = copyIn;

    ret = media_codec_queue_input(codec, &inBuf);
    if (ret != 0) {
        CLOGW("queue_input failed: %d", ret);
        return false;
    }
    return true;
#else
    (void)in;
    (void)inSize;
    return false;
#endif
}

} /* namespace camera */

