/****************************************************************************
 * frameworks/multimedia/camera/common/MediaCodecDecoder.h
 *
 * SPDX-License-Identifier: Apache-2.0
 *
 * Generic MediaCodec-backed frame decoder (an IFrameDecoder implementation).
 * Shares the codec lifecycle + input-submit plumbing with the encoder via
 * MediaCodecBase; adds the decode direction: async dequeue of the decoded
 * output and normalization to packed NV12.
 *
 * The concrete codec is selected by the input fourcc -> MIME mapping, so the
 * same class serves MJPEG today and H.264/HEVC preview later without new code.
 *
 * Thread safety: all public methods must be called under decoderMutex_.
 ****************************************************************************/

#pragma once

#include <cstddef>
#include <cstdint>

#include "FrameFormat.h"
#include "IFrameDecoder.h"
#include "MediaCodecBase.h"

namespace camera {

class MediaCodecDecoder : public IFrameDecoder, public MediaCodecBase {
public:
    MediaCodecDecoder() = default;

    bool configure(const FrameFormat& in, FrameFormat* out) override;
    bool decode(const uint8_t* in, size_t inSize, uint8_t* out, size_t outSize,
                size_t* actualOutputSize) override;
    bool isReady() const override {
        return configured_;
    }
    const FrameFormat& outputFormat() const override {
        return outputFormat_;
    }
    const char* backendName() const override {
        return "MediaCodec-HW";
    }

    /** Probe whether a MediaCodec decoder exists for the given input fourcc. */
    static bool available(uint32_t srcFourcc) {
        return availableFor(srcFourcc, /*isEncoder=*/false);
    }

private:
    uint32_t outputPixFmt_ = 0;    /* V4L2 pixel format of decoder output */
    uint32_t outputStride_ = 0;    /* driver-reported output row stride (0 => packed) */
    FrameFormat outputFormat_;     /* actual decoded output geometry (NV12) */

    /** Convert I420 planar to NV12 (padding-aware via explicit strides). */
    static void i420ToNv12(const uint8_t* i420, uint8_t* nv12, uint32_t width, uint32_t height,
                           uint32_t yStride, uint32_t uvStride);
};

} /* namespace camera */
========== common/MediaCodecDecoder.cpp ==========
/****************************************************************************
 * frameworks/multimedia/camera/hal/MediaCodecDecoder.cpp
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#define LOG_TAG "MediaCodecDecoder"
#include "MediaCodecDecoder.h"

#include <algorithm>
#include <cstring>

#include "CameraUtils.h"

#ifdef CONFIG_MEDIA_CODEC
#include <media_codec.h>
#include <sys/videoio.h>
#endif

namespace camera {

bool MediaCodecDecoder::configure(const FrameFormat& in, FrameFormat* out) {
#ifdef CONFIG_MEDIA_CODEC
    if (configured_) {
        destroyCodec();
    }

    const char* mime = fourccToMime(in.fourcc);
    if (!mime || in.width == 0 || in.height == 0) {
        CLOGE("unsupported input fourcc=0x%08x %ux%u", in.fourcc, in.width, in.height);
        return false;
    }

    width_ = in.width;
    height_ = in.height;

    codec_ = media_codec_create_by_type(mime, MEDIA_CODEC_DECODER);
    if (!codec_) {
        CLOGW("create failed for mime=%s", mime);
        return false;
    }

    /* pix_format = 0 lets the driver auto-detect output via VIDIOC_ENUM_FMT.
     * Sim outputs YUV420, BES HW outputs NV12. */
    media_codec_format_t fmt = {};
    fmt.mime = mime;
    fmt.width = width_;
    fmt.height = height_;
    fmt.pix_format = 0;

    if (media_codec_configure(static_cast<media_codec_t>(codec_), &fmt) != 0) {
        CLOGW("media_codec_configure failed");
        destroyCodec();
        return false;
    }
    if (media_codec_start(static_cast<media_codec_t>(codec_)) != 0) {
        CLOGW("media_codec_start failed");
        destroyCodec();
        return false;
    }

    media_codec_format_t outFmt = {};
    if (media_codec_get_output_format(static_cast<media_codec_t>(codec_), &outFmt) == 0) {
        outputPixFmt_ = outFmt.pix_format;
        outputStride_ = outFmt.stride; /* 0 => not reported, treat as packed */
        CLOGI("OK %ux%u, output fmt=0x%08x stride=%u", width_, height_, outputPixFmt_,
              outputStride_);
    } else {
        outputPixFmt_ = 0;
        outputStride_ = 0;
        CLOGW("get_output_format failed, assuming NV12 packed");
    }

    /* Delivered to the caller as packed NV12 regardless of driver format. */
    outputFormat_ = FrameFormat::nv12(width_, height_);
    configured_ = true;
    if (out) {
        *out = outputFormat_;
    }
    return true;
#else
    (void)in;
    (void)out;
    return false;
#endif
}

bool MediaCodecDecoder::decode(const uint8_t* in, size_t inSize, uint8_t* out, size_t outSize,
                               size_t* actualSize) {
#ifdef CONFIG_MEDIA_CODEC
    if (!configured_ || !in || inSize == 0 || !out || !actualSize) {
        return false;
    }
    auto* codec = static_cast<media_codec_t>(codec_);

    if (!submitInput(in, inSize)) {
        return false;
    }

    media_codec_buffer_t outBuf = {};
    int ret = media_codec_dequeue_output(codec, &outBuf, 20000);
    if (ret != 0) {
        CLOGW("dequeue_output failed: %d", ret);
        return false;
    }

    if (outBuf.data == nullptr || outBuf.size == 0) {
        CLOGW("output buffer data is null or empty");
        media_codec_release_output(codec, outBuf.index, false);
        return false;
    }

    /* Copy decoded data to caller buffer, converting format if needed. */
    if (outputPixFmt_ == V4L2_PIX_FMT_YUV420) {
        /* Driver outputs I420 planar -> convert to NV12. Use the driver stride
         * (bytesperline) rather than assuming stride==width so a padded layout
         * converts correctly. V4L2 I420 uses yStride luma, yStride/2 chroma. */
        const uint32_t yStride = outputStride_ > 0 ? outputStride_ : width_;
        const uint32_t uvStride = yStride / 2;
        const size_t i420Size =
                static_cast<size_t>(yStride) * height_ + static_cast<size_t>(uvStride) * height_;
        const size_t nv12Size = static_cast<size_t>(width_) * height_ * 3 / 2;
        if (outSize < nv12Size) {
            CLOGW("output buffer too small for NV12 (%zu < %zu)", outSize, nv12Size);
            media_codec_release_output(codec, outBuf.index, false);
            return false;
        }
        /* A short read would leave the tail of i420Buf_ stale and corrupt the
         * chroma plane after conversion -- reject instead. */
        if (outBuf.size < i420Size) {
            CLOGW("short I420 output (%u < %zu)", outBuf.size, i420Size);
            media_codec_release_output(codec, outBuf.index, false);
            return false;
        }
        if (i420Buf_.size() < i420Size) {
            i420Buf_.resize(i420Size);
        }
        memcpy(i420Buf_.data(), outBuf.data, i420Size);
        media_codec_release_output(codec, outBuf.index, false);
        i420ToNv12(i420Buf_.data(), out, width_, height_, yStride, uvStride);
        *actualSize = nv12Size;
    } else {
        /* NV12 or other packed format -- direct copy. */
        size_t copyOut = std::min(static_cast<size_t>(outBuf.size), outSize);
        memcpy(out, outBuf.data, copyOut);
        *actualSize = copyOut;
        media_codec_release_output(codec, outBuf.index, false);
    }
    return true;
#else
    (void)in;
    (void)inSize;
    (void)out;
    (void)outSize;
    (void)actualSize;
    return false;
#endif
}

/* static */
void MediaCodecDecoder::i420ToNv12(const uint8_t* i420, uint8_t* nv12, uint32_t width,
                                   uint32_t height, uint32_t yStride, uint32_t uvStride) {
    const uint32_t ySize = width * height;
    const uint8_t* srcY = i420;
    const uint8_t* srcU = i420 + yStride * height;
    const uint8_t* srcV = srcU + uvStride * (height / 2);

    uint8_t* dstY = nv12;
    for (uint32_t row = 0; row < height; row++) {
        memcpy(dstY + row * width, srcY + row * yStride, width);
    }

    uint8_t* dstUV = nv12 + ySize;
    for (uint32_t row = 0; row < height / 2; row++) {
        for (uint32_t col = 0; col < width / 2; col++) {
            dstUV[row * width + col * 2] = srcU[row * uvStride + col];
            dstUV[row * width + col * 2 + 1] = srcV[row * uvStride + col];
        }
    }
}

