/****************************************************************************
 * frameworks/multimedia/camera/common/MediaCodecEncoder.h
 *
 * SPDX-License-Identifier: Apache-2.0
 *
 * Generic MediaCodec-backed frame encoder (an IFrameEncoder implementation).
 * The symmetric counterpart of MediaCodecDecoder: shares the codec lifecycle +
 * input-submit plumbing via MediaCodecBase; adds the encode direction. Input to
 * the HAL is always packed NV12; output is a compressed unit.
 *
 * The raw input format the backend actually accepts is negotiated at
 * configure() time: NV12 is preferred (HW-friendly, zero-copy), falling back
 * to I420 (e.g. the sim x264 encoder only takes YUV420), in which case NV12 is
 * converted to I420 before feeding the codec.
 *
 * The concrete codec is selected by the target fourcc -> MIME mapping, so the
 * same class serves H.264 today and JPEG once a backend exists.
 *
 * Thread safety: all public methods must be called under decoderMutex_.
 ****************************************************************************/

#pragma once

#include <cstddef>
#include <cstdint>

#include "FrameFormat.h"
#include "IFrameEncoder.h"
#include "MediaCodecBase.h"

namespace camera {

class MediaCodecEncoder : public IFrameEncoder, public MediaCodecBase {
public:
    explicit MediaCodecEncoder(uint32_t dstFourcc) : dstFourcc_(dstFourcc) {}

    bool configure(const FrameFormat& in, const Params& params) override;
    bool encode(const uint8_t* nv12, size_t nv12Size, uint8_t* out, size_t outCap,
                size_t* actualSize, bool* isKeyFrame) override;
    bool isReady() const override {
        return configured_;
    }
    uint32_t outputFourcc() const override {
        return dstFourcc_;
    }
    const char* backendName() const override {
        return "MediaCodec-HW";
    }

    /** Probe whether a MediaCodec encoder exists for the given target fourcc. */
    static bool available(uint32_t dstFourcc) {
        return availableFor(dstFourcc, /*isEncoder=*/true);
    }

private:
    uint32_t dstFourcc_;
    uint32_t inputPixFmt_ = 0;    /* V4L2 raw format the backend accepts */
    bool inputNeedsI420_ = false; /* backend takes I420, convert NV12 first */

    /** Create + configure + start the codec for one raw input format. */
    bool tryConfigure(const char* mime, uint32_t pixFmt, const Params& params);

    /** Convert packed NV12 to I420 planar (Y then U then V, stride==width). */
    static void nv12ToI420(const uint8_t* nv12, uint8_t* i420, uint32_t width, uint32_t height);
};

