#define LOG_TAG "MediaCodecEncoder"
#include "MediaCodecEncoder.h"

#include <algorithm>
#include <cstring>

#include "CameraUtils.h"

#ifdef CONFIG_MEDIA_CODEC
#include <media_codec.h>
#include <sys/videoio.h>
#endif

namespace camera {

/* Encoder defaults when the caller leaves Params fields at 0. */
static constexpr uint32_t kDefaultFramerate = 30;
static constexpr uint32_t kDefaultBitrate = 4000000; /* 4 Mbps */

bool MediaCodecEncoder::tryConfigure(const char* mime, uint32_t pixFmt, const Params& params) {
#ifdef CONFIG_MEDIA_CODEC
    codec_ = media_codec_create_by_type(mime, MEDIA_CODEC_ENCODER);
    if (!codec_) {
        return false;
    }

    media_codec_format_t fmt = {};
    fmt.mime = mime;
    fmt.width = width_;
    fmt.height = height_;
    fmt.pix_format = pixFmt;
    fmt.framerate = params.framerate ? params.framerate : kDefaultFramerate;
    fmt.bitrate = params.bitrate ? params.bitrate : kDefaultBitrate;

    if (media_codec_configure(static_cast<media_codec_t>(codec_), &fmt) != 0) {
        destroyCodec();
        return false;
    }
    if (media_codec_start(static_cast<media_codec_t>(codec_)) != 0) {
        destroyCodec();
        return false;
    }
    inputPixFmt_ = pixFmt;
    return true;
#else
    (void)mime;
    (void)pixFmt;
    (void)params;
    return false;
#endif
}

bool MediaCodecEncoder::configure(const FrameFormat& in, const Params& params) {
#ifdef CONFIG_MEDIA_CODEC
    if (configured_) {
        destroyCodec();
    }

    const char* mime = fourccToMime(dstFourcc_);
    /* Input must be NV12 -- the canonical intermediate the data plane owns. */
    if (!mime || in.fourcc != pixfmt::NV12 || in.width == 0 || in.height == 0) {
        CLOGE("bad config: dst=0x%08x in.fourcc=0x%08x %ux%u", dstFourcc_, in.fourcc, in.width,
              in.height);
        return false;
    }

    width_ = in.width;
    height_ = in.height;

    /* Prefer NV12 (HW-friendly). Fall back to I420 for backends that only take
     * planar YUV420 (e.g. the sim x264 encoder), converting NV12 on encode. */
    if (tryConfigure(mime, V4L2_PIX_FMT_NV12, params)) {
        inputNeedsI420_ = false;
    } else if (tryConfigure(mime, V4L2_PIX_FMT_YUV420, params)) {
        inputNeedsI420_ = true;
    } else {
        CLOGW("configure failed for mime=%s (tried NV12 and I420)", mime);
        return false;
    }

    CLOGI("OK %ux%u -> mime=%s input=%s bitrate=%u fps=%u", width_, height_, mime,
          inputNeedsI420_ ? "I420" : "NV12", params.bitrate ? params.bitrate : kDefaultBitrate,
          params.framerate ? params.framerate : kDefaultFramerate);
    configured_ = true;
    return true;
#else
    (void)in;
    (void)params;
    return false;
#endif
}

bool MediaCodecEncoder::encode(const uint8_t* nv12, size_t nv12Size, uint8_t* out, size_t outCap,
                               size_t* actualSize, bool* isKeyFrame) {
#ifdef CONFIG_MEDIA_CODEC
    if (!configured_ || !nv12 || nv12Size == 0 || !out || outCap == 0 || !actualSize) {
        return false;
    }
    const size_t frameSize = static_cast<size_t>(width_) * height_ * 3 / 2;
    if (nv12Size < frameSize) {
        CLOGW("input too small for NV12 (%zu < %zu)", nv12Size, frameSize);
        return false;
    }

    /* Feed the backend's accepted raw format: NV12 directly, or I420 after
     * de-interleaving the NV12 chroma. */
    const uint8_t* raw = nv12;
    if (inputNeedsI420_) {
        if (i420Buf_.size() < frameSize) {
            i420Buf_.resize(frameSize);
        }
        nv12ToI420(nv12, i420Buf_.data(), width_, height_);
        raw = i420Buf_.data();
    }

    auto* codec = static_cast<media_codec_t>(codec_);

    if (!submitInput(raw, frameSize)) {
        return false;
    }

    /* Encoders may report a one-off format change before the first frame;
     * retry a bounded number of times so a single encode() still succeeds. */
    media_codec_buffer_t outBuf = {};
    int ret = 0;
    int attempts = 0;
    do {
        outBuf = media_codec_buffer_t{};
        ret = media_codec_dequeue_output(codec, &outBuf, 20000);
    } while (ret == MEDIA_CODEC_INFO_OUTPUT_FORMAT_CHANGED && ++attempts < 4);

    if (ret != 0) {
        CLOGW("dequeue_output failed: %d", ret);
        return false;
    }
    if (outBuf.data == nullptr || outBuf.size == 0) {
        CLOGW("output buffer null or empty");
        media_codec_release_output(codec, outBuf.index, false);
        return false;
    }
    if (outBuf.size > outCap) {
        CLOGW("output too large for buffer (%u > %zu)", outBuf.size, outCap);
        media_codec_release_output(codec, outBuf.index, false);
        return false;
    }

    memcpy(out, outBuf.data, outBuf.size);
    *actualSize = outBuf.size;
    if (isKeyFrame) {
        *isKeyFrame = (outBuf.flags & MEDIA_CODEC_FLAG_KEY_FRAME) != 0;
    }
    media_codec_release_output(codec, outBuf.index, false);
    return true;
#else
    (void)nv12;
    (void)nv12Size;
    (void)out;
    (void)outCap;
    (void)actualSize;
    (void)isKeyFrame;
    return false;
#endif
}

/* static */
void MediaCodecEncoder::nv12ToI420(const uint8_t* nv12, uint8_t* i420, uint32_t width,
                                   uint32_t height) {
    const uint32_t ySize = width * height;
    const uint32_t cSize = ySize / 4;

    memcpy(i420, nv12, ySize); /* Y plane copied as-is */

    const uint8_t* srcUV = nv12 + ySize;
    uint8_t* dstU = i420 + ySize;
    uint8_t* dstV = dstU + cSize;
    for (uint32_t i = 0; i < cSize; i++) {
        dstU[i] = srcUV[i * 2];
        dstV[i] = srcUV[i * 2 + 1];
    }
}

