#pragma once

#include <cstddef>
#include <cstdint>
#include <vector>

namespace camera {

// ============================================================================
// RawFrame -- a CPU-accessible (mmap'd) raw frame: pointer + geometry + format.
//
// Used by the service codec pipeline as the unit passed between decode, pixel
// conversion and encode. `format` is a HAL_PIXEL_FORMAT_* value. `stride` is the
// luma/row stride in bytes; 0 means "packed" (stride == width * bytes-per-pixel
// for RGB, or width for the Y plane of NV12).
// ============================================================================
struct RawFrame {
    uint8_t* data = nullptr;
    size_t size = 0;
    uint32_t width = 0;
    uint32_t height = 0;
    uint32_t stride = 0; /* row stride in bytes; 0 => packed */
    int32_t format = 0;  /* HAL_PIXEL_FORMAT_* */
};

// ============================================================================
// PixelConverter -- pure pixel/color-space conversion over libyuv.
//
// The canonical input is packed NV12 (Y plane + interleaved UV, 4:2:0). The
// converter turns it into a target raw format (RGBA/RGBX/BGRA/RGB565/RGB888,
// NV12 passthrough, or YV12), scaling first when the destination geometry
// differs. It does NOT touch compressed formats -- decode/encode is the codec's
// job (IFrameDecoder/IFrameEncoder). This is the "pixel" stage of
// CameraFormatConverter's decode -> pixel -> encode plan.
//
// Thread safety: not internally synchronized. A converter owns a scratch buffer
// for scaling, so one instance must be driven by a single thread (the pipeline
// worker), matching the codec's "serialized by the caller" contract.
// ============================================================================
class PixelConverter {
public:
    // True when a pixel/scale step is required: formats differ or geometry
    // differs. Same format AND same geometry => false (caller can memcpy/ref).
    static bool needed(int32_t srcFmt, int32_t dstFmt, uint32_t sw, uint32_t sh, uint32_t dw,
                       uint32_t dh);

    // Convert `srcNv12` (packed NV12, by contract) into `dst`.
    //   - dst->format selects the target (HAL_PIXEL_FORMAT_*).
    //   - dst->data must point to a buffer of at least the target size;
    //     dst->stride (0 => packed) sets the output row stride.
    //   - When dst geometry != src geometry the source is scaled first.
    // Returns 0 on success, or a negative errno (-EINVAL bad args,
    // -ENOTSUP unsupported target format).
    int convert(const RawFrame& srcNv12, RawFrame* dst);

    // Bytes-per-pixel of an RGB HAL format, or 0 if not a supported packed RGB.
    static uint32_t rgbBytesPerPixel(int32_t halFormat);

private:
    // Scale packed NV12 `src` to `dstW x dstH` into scaleBuf_, returning a
    // RawFrame view over the scratch. Returns false on failure.
    bool scaleNv12(const RawFrame& src, uint32_t dstW, uint32_t dstH, RawFrame* out);

    std::vector<uint8_t> scaleBuf_; /* scratch for NV12 rescale */
};

