#include "PixelConverter.h"

#include <system/graphics-base-v1.0.h>

#include <cerrno>
#include <cstring>

#ifdef CONFIG_LIBYUV
#include <libyuv.h>
#endif

namespace camera {

// Byte-order note (libyuv vs HAL):
//   HAL RGBA_8888 = bytes R,G,B,A  == libyuv ABGR
//   HAL BGRA_8888 = bytes B,G,R,A  == libyuv ARGB
//   HAL RGB_565   ==                  libyuv RGB565
//   HAL RGB_888   = bytes R,G,B    == libyuv RGB24

/* static */
bool PixelConverter::needed(int32_t srcFmt, int32_t dstFmt, uint32_t sw, uint32_t sh, uint32_t dw,
                            uint32_t dh) {
    return srcFmt != dstFmt || sw != dw || sh != dh;
}

/* static */
uint32_t PixelConverter::rgbBytesPerPixel(int32_t halFormat) {
    switch (halFormat) {
        case HAL_PIXEL_FORMAT_RGBA_8888:
        case HAL_PIXEL_FORMAT_RGBX_8888:
        case HAL_PIXEL_FORMAT_BGRA_8888:
            return 4;
        case HAL_PIXEL_FORMAT_RGB_888:
            return 3;
        case HAL_PIXEL_FORMAT_RGB_565:
            return 2;
        default:
            return 0;
    }
}

bool PixelConverter::scaleNv12(const RawFrame& src, uint32_t dstW, uint32_t dstH, RawFrame* out) {
#ifdef CONFIG_LIBYUV
    const uint32_t sStride = src.stride ? src.stride : src.width;
    const size_t dstNv12 = static_cast<size_t>(dstW) * dstH * 3 / 2;
    if (scaleBuf_.size() < dstNv12) {
        scaleBuf_.resize(dstNv12);
    }
    uint8_t* dY = scaleBuf_.data();
    uint8_t* dUV = scaleBuf_.data() + static_cast<size_t>(dstW) * dstH;
    const uint8_t* sY = src.data;
    const uint8_t* sUV = src.data + static_cast<size_t>(sStride) * src.height;

    if (libyuv::NV12Scale(sY, sStride, sUV, sStride, src.width, src.height, dY, dstW, dUV, dstW,
                          dstW, dstH, libyuv::kFilterBilinear) != 0) {
        return false;
    }
    out->data = scaleBuf_.data();
    out->size = dstNv12;
    out->width = dstW;
    out->height = dstH;
    out->stride = dstW;
    out->format = src.format;
    return true;
#else
    (void)src;
    (void)dstW;
    (void)dstH;
    (void)out;
    return false;
#endif
}

int PixelConverter::convert(const RawFrame& srcNv12, RawFrame* dst) {
    if (!srcNv12.data || !dst || !dst->data) {
        return -EINVAL;
    }
    if (srcNv12.width == 0 || srcNv12.height == 0 || dst->width == 0 || dst->height == 0) {
        return -EINVAL;
    }

    // Bring the NV12 source to the destination geometry (scale if needed).
    RawFrame nv12 = srcNv12;
    if (srcNv12.width != dst->width || srcNv12.height != dst->height) {
#ifdef CONFIG_LIBYUV
        if (!scaleNv12(srcNv12, dst->width, dst->height, &nv12)) {
            return -EINVAL;
        }
#else
        return -ENOTSUP;
#endif
    }

    const uint32_t w = dst->width;
    const uint32_t h = dst->height;
    const uint32_t syStride = nv12.stride ? nv12.stride : w;
    const uint8_t* srcY = nv12.data;
    const uint8_t* srcUV = nv12.data + static_cast<size_t>(syStride) * h;
    const uint32_t suvStride = syStride; /* NV12: UV stride == luma stride */

    switch (dst->format) {
        case HAL_PIXEL_FORMAT_RGBA_8888:
        case HAL_PIXEL_FORMAT_RGBX_8888: {
#ifdef CONFIG_LIBYUV
            const uint32_t dstStride = dst->stride ? dst->stride : w * 4;
            if (dst->size && dst->size < static_cast<size_t>(dstStride) * h) return -EINVAL;
            return libyuv::NV12ToABGR(srcY, syStride, srcUV, suvStride, dst->data, dstStride, w,
                                      h) == 0
                           ? 0
                           : -EINVAL;
#else
            return -ENOTSUP;
#endif
        }
        case HAL_PIXEL_FORMAT_BGRA_8888: {
#ifdef CONFIG_LIBYUV
            const uint32_t dstStride = dst->stride ? dst->stride : w * 4;
            if (dst->size && dst->size < static_cast<size_t>(dstStride) * h) return -EINVAL;
            return libyuv::NV12ToARGB(srcY, syStride, srcUV, suvStride, dst->data, dstStride, w,
                                      h) == 0
                           ? 0
                           : -EINVAL;
#else
            return -ENOTSUP;
#endif
        }
        case HAL_PIXEL_FORMAT_RGB_565: {
#ifdef CONFIG_LIBYUV
            const uint32_t dstStride = dst->stride ? dst->stride : w * 2;
            if (dst->size && dst->size < static_cast<size_t>(dstStride) * h) return -EINVAL;
            return libyuv::NV12ToRGB565(srcY, syStride, srcUV, suvStride, dst->data, dstStride, w,
                                        h) == 0
                           ? 0
                           : -EINVAL;
#else
            return -ENOTSUP;
#endif
        }
        case HAL_PIXEL_FORMAT_RGB_888: {
#ifdef CONFIG_LIBYUV
            const uint32_t dstStride = dst->stride ? dst->stride : w * 3;
            if (dst->size && dst->size < static_cast<size_t>(dstStride) * h) return -EINVAL;
            return libyuv::NV12ToRGB24(srcY, syStride, srcUV, suvStride, dst->data, dstStride, w,
                                       h) == 0
                           ? 0
                           : -EINVAL;
#else
            return -ENOTSUP;
#endif
        }
        case HAL_PIXEL_FORMAT_YV12: {
#ifdef CONFIG_LIBYUV
            /* YV12 plane order is Y, V, U at w/2 stride. NV12ToI420 writes U to
             * dst_u and V to dst_v -- point them at the swapped locations. */
            const size_t ySize = static_cast<size_t>(w) * h;
            const uint32_t cStride = w / 2;
            const size_t cSize = static_cast<size_t>(cStride) * (h / 2);
            if (dst->size && dst->size < ySize + 2 * cSize) return -EINVAL;
            uint8_t* dstY = dst->data;
            uint8_t* dstV = dst->data + ySize;
            uint8_t* dstU = dst->data + ySize + cSize;
            return libyuv::NV12ToI420(srcY, syStride, srcUV, suvStride, dstY, w, dstU, cStride, dstV,
                                      cStride, w, h) == 0
                           ? 0
                           : -EINVAL;
#else
            return -ENOTSUP;
#endif
        }
        case HAL_PIXEL_FORMAT_YCBCR_420_888: {
            /* Deliver packed NV12 bytes (a valid concrete 420_888 layout). */
            const size_t nv12Size = static_cast<size_t>(w) * h * 3 / 2;
            if (dst->size && dst->size < nv12Size) return -EINVAL;
            if (syStride == w) {
                memcpy(dst->data, nv12.data, nv12Size);
            } else {
                for (uint32_t r = 0; r < h; r++) {
                    memcpy(dst->data + static_cast<size_t>(r) * w, srcY + static_cast<size_t>(r) * syStride, w);
                }
                uint8_t* dUV = dst->data + static_cast<size_t>(w) * h;
                for (uint32_t r = 0; r < h / 2; r++) {
                    memcpy(dUV + static_cast<size_t>(r) * w, srcUV + static_cast<size_t>(r) * suvStride, w);
                }
            }
            return 0;
        }
        default:
            return -ENOTSUP;
    }
}

