#pragma once

#include <cstddef>
#include <cstdint>
#include <memory>
#include <vector>

#include "IFrameDecoder.h"
#include "IFrameEncoder.h"
#include "PixelConverter.h"

namespace camera {

// ============================================================================
// CameraFormatConverter -- orchestrates a one-frame format transform for the
// service codec pipeline: decode -> pixel -> encode, using canonical NV12 as
// the pivot. It ties together the codec abstractions (IFrameDecoder /
// IFrameEncoder, shared in common/) and the pixel stage (PixelConverter).
//
// Formats are HAL_PIXEL_FORMAT_* stream formats. Compressed streams use
// HAL_PIXEL_FORMAT_BLOB (JPEG family, fourcc MJPG on the codec side). Raw
// streams are RGB (RGBA/RGBX/BGRA/RGB888/RGB565) or YUV 4:2:0 (YCBCR_420_888 /
// YV12), with the decoder's packed NV12 output treated as canonical YCBCR_420_888.
//
// open() inspects (src,dst,geometry) + backend availability and fixes a Plan;
// if a required codec backend is missing (e.g. sim has no M2M JPEG encoder) it
// returns false so the caller can reject the stream up front. process() then
// executes the plan on one frame.
//
// Thread safety: not internally synchronized; a converter owns scratch buffers,
// so one instance is driven by a single thread (the pipeline worker).
// ============================================================================
class CameraFormatConverter {
public:
    struct Plan {
        bool passthrough = false; /* src == dst, byte copy */
        bool decode = false;      /* compressed src -> NV12 */
        bool pixel = false;       /* NV12 -> target raw (libyuv) */
        bool encode = false;      /* NV12 -> compressed dst */
    };

    // Decide the Plan for (src,dst) at the given geometries and build the
    // decoder/encoder as needed. Returns false when a required backend is
    // unavailable or the combination is unsupported.
    bool open(int32_t srcFmt, int32_t dstFmt, uint32_t sw, uint32_t sh, uint32_t dw, uint32_t dh);

    // Transform one frame per the Plan. `src` is the source raw/compressed
    // frame; result is written into `dst` (already-sized output buffer).
    // For compressed output *actualSize gets the byte count; for raw output it
    // gets the fixed raw size. Returns 0 or a negative errno.
    int process(const RawFrame& src, RawFrame* dst, size_t* actualSize);

    const Plan& plan() const { return plan_; }
    bool isOpen() const { return open_; }
    void close();

    // Classification helpers (HAL_PIXEL_FORMAT_*).
    static bool isCompressed(int32_t halFmt);
    static bool isYuv420(int32_t halFmt);

private:
    Plan plan_;
    bool open_ = false;
    int32_t srcFmt_ = 0;
    int32_t dstFmt_ = 0;
    uint32_t sw_ = 0, sh_ = 0, dw_ = 0, dh_ = 0;

    std::unique_ptr<IFrameDecoder> decoder_; /* shared codec (common/) */
    std::unique_ptr<IFrameEncoder> encoder_; /* shared codec (common/) */
    PixelConverter pixel_;

    std::vector<uint8_t> nv12_;       /* decoded NV12 @ source geometry */
    std::vector<uint8_t> nv12Scaled_; /* NV12 @ dst geometry, for encode+scale */
};

