// Canonical intermediate: the decoder emits packed NV12, treated as
// YCBCR_420_888 for pixel-stage comparison/delivery.
static constexpr int32_t kCanonYuv = HAL_PIXEL_FORMAT_YCBCR_420_888;

/* static */
bool CameraFormatConverter::isCompressed(int32_t halFmt) {
    /* BLOB carries a JPEG-family compressed unit (fourcc MJPG on codec side). */
    return halFmt == HAL_PIXEL_FORMAT_BLOB;
}

/* static */
bool CameraFormatConverter::isYuv420(int32_t halFmt) {
    return halFmt == HAL_PIXEL_FORMAT_YCBCR_420_888 || halFmt == HAL_PIXEL_FORMAT_YV12 ||
           halFmt == HAL_PIXEL_FORMAT_YCRCB_420_SP;
}

bool CameraFormatConverter::open(int32_t srcFmt, int32_t dstFmt, uint32_t sw, uint32_t sh,
                                 uint32_t dw, uint32_t dh) {
    close();
    if (sw == 0 || sh == 0 || dw == 0 || dh == 0) {
        return false;
    }

    srcFmt_ = srcFmt;
    dstFmt_ = dstFmt;
    sw_ = sw;
    sh_ = sh;
    dw_ = dw;
    dh_ = dh;

    const bool srcC = isCompressed(srcFmt);
    const bool dstC = isCompressed(dstFmt);

    Plan p;
    if (srcC && dstC) {
        /* JPEG-family both sides: byte-copy if identical, else decode+re-encode. */
        if (srcFmt == dstFmt && sw == dw && sh == dh) {
            p.passthrough = true;
        } else {
            p.decode = true;
            p.encode = true;
        }
    } else if (srcC && !dstC) {
        /* compressed -> raw: decode to NV12, then pixel-convert unless the
         * target is YCBCR_420_888 at the same geometry (deliver NV12 as-is). */
        p.decode = true;
        p.pixel = PixelConverter::needed(kCanonYuv, dstFmt, sw, sh, dw, dh);
    } else if (!srcC && dstC) {
        /* raw -> compressed: normalize/scale to NV12 @ dst geometry, then encode. */
        p.encode = true;
        p.pixel = (srcFmt != kCanonYuv) || sw != dw || sh != dh;
    } else {
        /* raw -> raw. */
        if (PixelConverter::needed(srcFmt, dstFmt, sw, sh, dw, dh)) {
            p.pixel = true;
        } else {
            p.passthrough = true;
        }
    }

    /* Build the codec backends the plan needs; reject if unavailable.
     *
     * decode/encode are compressed-codec operations gated by CONFIG_MEDIA_CODEC
     * (the MediaCodec backend + its factories live behind it). The pure pixel
     * path (raw->raw) never sets p.decode/p.encode, so it is fully usable with
     * libyuv alone -- that is the codec/format-conversion decoupling. Without a
     * codec, any plan that needs decode/encode is rejected up front. */
    if (p.decode || p.encode) {
#ifdef CONFIG_MEDIA_CODEC
        if (p.decode) {
            decoder_ = createFrameDecoder(pixfmt::MJPG, pixfmt::NV12);
            if (!decoder_) {
                close();
                return false;
            }
            FrameFormat in = FrameFormat::compressed(pixfmt::MJPG, sw, sh);
            FrameFormat out;
            if (!decoder_->configure(in, &out)) {
                close();
                return false;
            }
        }
        if (p.encode) {
            encoder_ = createFrameEncoder(pixfmt::MJPG);
            if (!encoder_) {
                /* e.g. sim has no M2M JPEG encoder -- reject up front. */
                close();
                return false;
            }
            IFrameEncoder::Params params; /* defaults; quality wiring is a TODO */
            if (!encoder_->configure(FrameFormat::nv12(dw, dh), params)) {
                close();
                return false;
            }
        }
#else
        /* No codec backend: cannot serve compressed decode/encode. */
        close();
        return false;
#endif
    }

    plan_ = p;
    open_ = true;
    return true;
}

int CameraFormatConverter::process(const RawFrame& src, RawFrame* dst, size_t* actualSize) {
    if (!open_ || !dst || !dst->data || !src.data) {
        return -EINVAL;
    }
    size_t produced = 0;

    if (plan_.passthrough) {
        const size_t n = src.size < dst->size ? src.size : dst->size;
        memcpy(dst->data, src.data, n);
        if (actualSize) *actualSize = n;
        return 0;
    }

    /* Establish canonical NV12 @ source geometry in `cur`. */
    RawFrame cur;
    if (plan_.decode) {
        const size_t need = static_cast<size_t>(sw_) * sh_ * 3 / 2;
        if (nv12_.size() < need) nv12_.resize(need);
        size_t got = 0;
        if (!decoder_->decode(src.data, src.size, nv12_.data(), nv12_.size(), &got)) {
            return -EIO;
        }
        cur.data = nv12_.data();
        cur.size = got;
        cur.width = sw_;
        cur.height = sh_;
        cur.stride = sw_;
        cur.format = kCanonYuv;
    } else {
        cur = src;
        cur.width = sw_;
        cur.height = sh_;
        if (cur.stride == 0) cur.stride = sw_;
        cur.format = kCanonYuv; /* raw source assumed canonical NV12 */
    }

    if (plan_.encode) {
        /* Encoder wants NV12 @ dst geometry. Scale via pixel stage if needed. */
        RawFrame enc = cur;
        if (sw_ != dw_ || sh_ != dh_) {
            const size_t need = static_cast<size_t>(dw_) * dh_ * 3 / 2;
            if (nv12Scaled_.size() < need) nv12Scaled_.resize(need);
            RawFrame tmp;
            tmp.data = nv12Scaled_.data();
            tmp.size = nv12Scaled_.size();
            tmp.width = dw_;
            tmp.height = dh_;
            tmp.stride = dw_;
            tmp.format = kCanonYuv;
            int r = pixel_.convert(cur, &tmp);
            if (r != 0) return r;
            enc = tmp;
            enc.size = need;
        }
        size_t enced = 0;
        bool key = false;
        if (!encoder_->encode(enc.data, enc.size, dst->data, dst->size, &enced, &key)) {
            return -EIO;
        }
        produced = enced;
    } else if (plan_.pixel) {
        int r = pixel_.convert(cur, dst);
        if (r != 0) return r;
        /* Raw output size is fixed by dst geometry/format. */
        const uint32_t bpp = PixelConverter::rgbBytesPerPixel(dst->format);
        produced = bpp ? static_cast<size_t>(dst->width) * dst->height * bpp
                       : static_cast<size_t>(dst->width) * dst->height * 3 / 2;
    } else {
        /* Deliver canonical NV12 directly (decode-only, YUV420 same geometry). */
        const size_t n = cur.size < dst->size ? cur.size : dst->size;
        memcpy(dst->data, cur.data, n);
        produced = n;
    }

    if (actualSize) *actualSize = produced;
    return 0;
}

void CameraFormatConverter::close() {
    decoder_.reset();
    encoder_.reset();
    plan_ = Plan{};
    open_ = false;
}

